from test_profile_persistence import tests
from test_bufftap import test
test('Create with current settings retains general helpers through actual UI action',"BuffTap.db.helperThanks=true; BuffTap.db.helperDismiss=true; BuffTap.db.pauseResting=true; BuffTap:Options(); local p=BuffTap.options.profiles; p.name:SetText('My copy'); p.create.scripts.OnClick(); assert(BuffTap.profileDB:GetCurrentProfile()=='My copy' and BuffTap.db.helperThanks and BuffTap.db.helperDismiss and BuffTap.db.pauseResting)")
test('Default creation is confirmed and keeps original setup intact',"local old=BuffTap.profileDB:GetCurrentProfile(); BuffTap.db.helperThanks=true; BuffTap:Options(); local p=BuffTap.options.profiles; p.name:SetText('Defaults'); p.copyCurrent:SetChecked(false); p.create.scripts.OnClick(); assert(p.confirm.shown and BuffTap.profileDB:GetCurrentProfile()==old and BuffTap.db.helperThanks); p.accept.scripts.OnClick(); assert(BuffTap.profileDB:GetCurrentProfile()=='Defaults' and not BuffTap.db.helperThanks and BuffTap.profileDB.sv.profiles[old].helperThanks)")
test('Dedicated rename field preserves preferences and ignores create name',"BuffTap.db.helperThanks=true; BuffTap:Options(); local p=BuffTap.options.profiles; p.name:SetText('Unrelated new profile'); p.rename.scripts.OnClick(); p.renameName:SetText('Renamed'); p.renameSave.scripts.OnClick(); assert(BuffTap.profileDB:GetCurrentProfile()=='Renamed' and BuffTap.db.helperThanks and not BuffTap.profileDB.sv.profiles['Unrelated new profile'] and not p.renameDialog.shown)")
test('Rename Escape cancels without modifying profile',"local old=BuffTap.profileDB:GetCurrentProfile(); BuffTap:Options(); local p=BuffTap.options.profiles; p.rename.scripts.OnClick(); p.renameName:SetText('Discard'); p.renameName.scripts.OnEscapePressed(p.renameName); assert(not p.renameDialog.shown and BuffTap.profileDB:GetCurrentProfile()==old)")
test('Creation hint explicitly distinguishes current preferences from defaults',"BuffTap:Options(); local p=BuffTap.options.profiles; assert(p.createHint.text:find('Copies shared preferences',1,true)); p.copyCurrent:SetChecked(false); p.copyCurrent.scripts.OnClick(); assert(p.createHint.text:find('Starts with default',1,true) and p.create.text=='Create & switch')")
test('Legacy truthy checkbox value also copies rather than resetting helpers',"BuffTap.db.helperThanks=true; BuffTap:Options(); local p=BuffTap.options.profiles; p.name:SetText('Truthy'); p.copyCurrent.GetChecked=function() return 1 end; p.create.scripts.OnClick(); assert(BuffTap.profileDB:GetCurrentProfile()=='Truthy' and BuffTap.db.helperThanks)")
print('ALL',len(tests),'SCENARIOS PASSED')
